const chatData = $('Receive Day Number').first().json;
const messageText = chatData.chatInput || chatData.message || chatData.text || '';
const numberMatch = messageText.match(/\d+/);
const TARGET_DAY_INDEX = numberMatch ? parseInt(numberMatch[0]) : 8;

const allRows = $input.all().map(item => item.json);
const targetRow = allRows.find(row => String(row.day_index) === String(TARGET_DAY_INDEX));

if (!targetRow) throw new Error(`No row found with day_index = ${TARGET_DAY_INDEX}`);

const artistName = targetRow.artist_name || 'Unknown Artist';
const galleryTotal = targetRow.gallery_total || '111';
const completedRows = allRows.filter(row => row.exhibition_title && row.exhibition_title.trim() !== '');

const usedPractices = completedRows.map(r => (r.practice || '').substring(0, 100)).filter(p => p).join('\n- ');
const usedMusic = completedRows.map(r => { const m = r.cultural_music || ''; const match = m.match(/^([^(]+)/); return match ? match[1].trim() : ''; }).filter(m => m).join('\n- ');
const usedPoems = completedRows.map(r => `${r.poem_author || ''} - ${r.poem_work || ''}`).filter(p => p !== ' - ').join('\n- ');

return {
  dayIndex: TARGET_DAY_INDEX,
  galleryTotal: galleryTotal,
  artistName: artistName,
  usedPractices: usedPractices,
  usedMusic: usedMusic,
  usedPoems: usedPoems
};

const prevData = $('Build Content Prompt').first().json;
const inputData = $input.first().json;

let rawResponse = '';
if (inputData.content && Array.isArray(inputData.content)) {
  rawResponse = inputData.content.filter(i => i.type === 'text').map(i => i.text).join('');
} else if (inputData.message && inputData.message.content) {
  rawResponse = Array.isArray(inputData.message.content)
    ? inputData.message.content.filter(i => i.type === 'text').map(i => i.text).join('')
    : inputData.message.content;
} else if (inputData.text) {
  rawResponse = inputData.text;
}

if (!rawResponse) throw new Error('No response. Keys: ' + Object.keys(inputData).join(', '));

let content = {};
const jsonMatch = rawResponse.match(/\{[\s\S]*\}/);
if (jsonMatch) content = JSON.parse(jsonMatch[0]);
else throw new Error('No JSON found');

return {
  content,
  dayIndex: prevData.dayIndex,
  galleryTotal: prevData.galleryTotal,
  artistName: prevData.artistName
};

const data = $input.first().json;
const content = data.content;
const artistName = data.artistName;

// Create search queries for Wikimedia API
const paintings = [
  { field: 'hero', title: content.hero_title },
  { field: 'art2', title: content.art2_title },
  { field: 'style_art', title: content.style_art_title },
  { field: 'mini1', title: content.mini1_title },
  { field: 'mini2', title: content.mini2_title },
  { field: 'artist_portrait', title: artistName + ' self portrait' }
];

return paintings.map(p => ({
  json: {
    field: p.field,
    searchQuery: p.title + ' ' + artistName,
    content: content,
    dayIndex: data.dayIndex,
    galleryTotal: data.galleryTotal,
    artistName: artistName
  }
}));

const allResults = $input.all();
const prepareData = $('Prepare Wikimedia Searches').all();

const urls = {};

for (let i = 0; i < allResults.length; i++) {
  const result = allResults[i].json;
  const field = prepareData[i].json.field;

  try {
    const searchResults = result.query?.search || [];
    if (searchResults.length > 0) {
      // Get the file title
      const fileTitle = searchResults[0].title;
      // Convert to direct image URL
      // Format: File:NAME.jpg -> https://upload.wikimedia.org/wikipedia/commons/X/XX/NAME.jpg
      const fileName = fileTitle.replace('File:', '');
      const encodedName = encodeURIComponent(fileName.replace(/ /g, '_'));

      // Use Wikimedia's special page to get direct URL
      urls[field + '_url'] = `https://commons.wikimedia.org/wiki/Special:FilePath/${encodedName}?width=1000`;
    } else {
      urls[field + '_url'] = '';
    }
  } catch (e) {
    urls[field + '_url'] = '';
  }
}

// Get content from first item
const firstItem = prepareData[0].json;
const content = firstItem.content;

const combined = {
  day_index: String(firstItem.dayIndex),
  gallery_total: String(firstItem.galleryTotal),
  artist_name: firstItem.artistName,
  brand_name: 'Daily Sublime',
  exhibition_title: content.exhibition_title || '',
  hook_text: content.hook_text || '',
  why_it_matters: content.why_it_matters || '',
  notice_bullet_1: content.notice_bullet_1 || '',
  notice_bullet_2: content.notice_bullet_2 || '',
  notice_bullet_3: content.notice_bullet_3 || '',
  notice_bullet_4: content.notice_bullet_4 || '',
  notice_bullet_5: content.notice_bullet_5 || '',
  practice: content.practice || '',
  sticky_story: content.sticky_story || '',
  sticky_story_source_url: content.sticky_story_source_url || '',
  cultural_music: content.cultural_music || '',
  philosophy: content.philosophy || '',
  poem_line_1: content.poem_line_1 || '',
  poem_line_2: content.poem_line_2 || '',
  poem_author: content.poem_author || '',
  poem_work: content.poem_work || '',
  poem_source_url: content.poem_source_url || '',
  hero_title: content.hero_title || '',
  hero_year: content.hero_year || '',
  hero_alt: content.hero_alt || '',
  hero_url: urls.hero_url || '',
  art2_title: content.art2_title || '',
  art2_year: content.art2_year || '',
  art2_alt: content.art2_alt || '',
  art2_url: urls.art2_url || '',
  style_art_title: content.style_art_title || '',
  style_art_year: content.style_art_year || '',
  style_art_alt: content.style_art_alt || '',
  style_art_url: urls.style_art_url || '',
  mini1_title: content.mini1_title || '',
  mini1_year: content.mini1_year || '',
  mini1_alt: content.mini1_alt || '',
  mini1_url: urls.mini1_url || '',
  mini2_title: content.mini2_title || '',
  mini2_year: content.mini2_year || '',
  mini2_alt: content.mini2_alt || '',
  mini2_url: urls.mini2_url || '',
  artist_portrait_url: urls.artist_portrait_url || ''
};

return {
  combined,
  dayIndex: firstItem.dayIndex,
  artistName: firstItem.artistName
};

const data = $('Combine Content + URLs').first().json;
return {
  response: `✅ Edition generated for Day ${data.dayIndex}: ${data.artistName}

📝 Content by Claude Sonnet 4
🖼️ URLs from Wikimedia Commons API

Saved to Google Sheet.`
};
